struct invoice_repo { sqlite3 *db; };   /* opaque to callers */

int invoice_repo_find_by_id(struct invoice_repo *r, sqlite3_int64 id, struct invoice *out)
{
    sqlite3_stmt *st;
    if (sqlite3_prepare_v2(r->db, "SELECT id, amount, due FROM invoice WHERE id = ?",
                           -1, &st, NULL) != SQLITE_OK)
        return -1;                              /* SQL never leaves this translation unit */
    sqlite3_bind_int64(st, 1, id);
    int rc = (sqlite3_step(st) == SQLITE_ROW) ? invoice_from_row(st, out) : SQLITE_NOTFOUND;
    sqlite3_finalize(st);
    return rc;
}
